            int n = 11;
            longN v = new longN(n, Allocator.Temp);
            for (int i = 0; i < n; i++)
                v[i] = (long)(i - 5); // -5 .. 5, includes 0

            v.absInPlace();

            for (int i = 0; i < n; i++)
            {
                long o = (long)(i - 5);
                long expected = o < 0 ? (long)(-o) : o;
                Assert.IsTrue(v[i] == expected);
