                long o = (long)(i - 5);
                long expected = o < 0 ? (long)0 : o;
                Assert.IsTrue(v[i] == expected);
            }
        }

        private void MinBufTest()
        {
            int n = 11;
            longN x = new longN(n, Allocator.Temp);
            longN y = new longN(n, Allocator.Temp);
            for (int i = 0; i < n; i++)
            {
                x[i] = (long)(i - 5);   // -5 .. 5
                y[i] = (long)(5 - i);   // 5 .. -5  (crosses x)
            }
            longN y0 = y.Copy();

            x.minInPlace(y); // x = min(x, y) ; y untouched

            for (int i = 0; i < n; i++)
            {
                long a = (long)(i - 5), b = (long)(5 - i);
                Assert.IsTrue(x[i] == (a < b ? a : b));
                Assert.IsTrue(y[i] == y0[i]);
            }
        }

        private void MaxBufTest()
        {
            int n = 11;
            longN x = new longN(n, Allocator.Temp);
            longN y = new longN(n, Allocator.Temp);
            for (int i = 0; i < n; i++)
            {
                x[i] = (long)(i - 5);
                y[i] = (long)(5 - i);
            }
            longN y0 = y.Copy();

            x.maxInPlace(y); // x = max(x, y) ; y untouched

            for (int i = 0; i < n; i++)
            {
                long a = (long)(i - 5), b = (long)(5 - i);
                Assert.IsTrue(x[i] == (a > b ? a : b));
                Assert.IsTrue(y[i] == y0[i]);
            }
        }

        private void MadTest()
