                a[i] = (long)((i % 3) - 1); // -1,0,1
                b[i] = (long)((i % 2) + 1); // 1,2
                c[i] = (long)(i % 3);       // 0,1,2
            }
            longN a0 = a.Copy();
            longN b0 = b.Copy();
            longN c0 = c.Copy();

            a.madInPlace(b, c); // a = a*b + c ; ONLY a mutated

            for (int i = 0; i < n; i++)
            {
                Assert.IsTrue(a[i] == (long)(a0[i] * b0[i] + c0[i]));
                Assert.IsTrue(b[i] == b0[i]);
                Assert.IsTrue(c[i] == c0[i]);
            }
        }

